require __DIR__.'/app/bootstrap.php';$uriPath=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)??'/';$basePath=trim((string)(parse_url($config['base_url'],PHP_URL_PATH)??''),'/');if($basePath&&str_starts_with(trim($uriPath,'/'),$basePath))$uriPath=substr(trim($uriPath,'/'),strlen($basePath));$path=trim($uriPath,'/')?:'dashboard';$method=$_SERVER['REQUEST_METHOD'];
require ROOT.'/app/modules.php';
if($path==='login'&&$method==='POST'){verify_csrf();$q=$pdo->prepare("SELECT u.*,r.code role_code,r.name role_name,o.name office_name,o.type office_type,CASE WHEN o.type='RO' THEN o.id ELSE o.region_id END region_id FROM users u JOIN roles r ON r.id=u.role_id JOIN offices o ON o.id=u.office_id WHERE u.email=? AND u.is_active=1");$q->execute([strtolower(trim($_POST['email']??''))]);$x=$q->fetch();if($x&&password_verify($_POST['password']??'',$x['password_hash'])){session_regenerate_id(true);$_SESSION['user']=$x;$pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$x['id']]);audit($pdo,'login','user',$x['id']);go('dashboard');}flash('Email or password was not recognized.','error');go('login');}
if($path==='logout'&&$method==='POST'){verify_csrf();if(user())audit($pdo,'logout','user',user()['id']);$_SESSION=[];session_destroy();go('login');}
if($path==='login'){layout('Sign in',function(){?><div class="login"><i>J</i><small>JUTE CORPORATION OF INDIA LIMITED</small><h1>Welcome back</h1><p>Sign in to your JDP workspace.</p><?php $f=$_SESSION['_flash']??null;unset($_SESSION['_flash']);if($f):?><p class="notice error"><?=e($f[0])?></p><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Work email<input name="email" type="email" required autocomplete="username" placeholder="name@jci.gov.in"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="btn">Sign in　→</button></form><a class="forgot" href="<?=e(url('forgot-password'))?>">Forgot password?</a><small>Authorized JCI personnel only</small></div><?php });exit;}auth();require_access('dashboard');
if($path==='dashboard'){[$of,$rg]=scope();$where=$of?' AND r.office_id=?':($rg?' AND (o.id=? OR o.region_id=?)':'');$args=$of?[$of]:($rg?[$rg,$rg]:[]);$q=$pdo->prepare("SELECT r.status,COUNT(*) n FROM requisitions r JOIN offices o ON o.id=r.office_id WHERE 1=1 $where GROUP BY r.status");$q->execute($args);$stats=['pending'=>0,'approved'=>0,'rejected'=>0];foreach($q as $x)$stats[$x['status']]=(int)$x['n'];$q=$pdo->prepare("SELECT r.*,o.name office_name,u.name requester,p.sku product_sku,p.name product_name,au.name approved_by_name FROM requisitions r JOIN offices o ON o.id=r.office_id JOIN users u ON u.id=r.created_by LEFT JOIN products p ON p.id=r.product_id LEFT JOIN users au ON au.id=r.approved_by WHERE 1=1 $where ORDER BY r.created_at DESC LIMIT 6");$q->execute($args);$recent=$q->fetchAll();$q=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM inventory_items i JOIN offices o ON o.id=i.office_id WHERE 1=1'.($of?' AND i.office_id=?':($rg?' AND (o.id=? OR o.region_id=?)':'')));$q->execute($args);$stock=$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM vendors v WHERE active=1'.($of?' AND (v.office_id=? OR v.office_id IS NULL)':($rg?' AND (v.office_id IS NULL OR v.office_id=? OR v.office_id IN (SELECT id FROM offices WHERE region_id=?))':'')));$q->execute($of?[$of]:($rg?[$rg,$rg]:[]));$vendors=$q->fetchColumn();$roleCode=user()['role_code'];$context=match($roleCode){'ADMIN','HO_MANAGER'=>'Head Office enterprise view across the organization.','RO_MANAGER'=>'Regional portfolio for your Regional Office and its DPCs.','DPC_OFFICER'=>'Local operations for your assigned DPC.','APPROVER'=>'Approval desk for requests in your assigned scope.','AUDITOR'=>'Read-only oversight and audit activity for your scope.',default=>'Operations snapshot for your assigned office.'};$activityLabel='MONTH-TO-DATE SALES';$activityValue='₹ 0.00';$activityFoot='Recorded sales value';$showActivity=can_access('sales');if($roleCode==='APPROVER'){$aq=$pdo->prepare("SELECT COUNT(*) FROM requisitions r JOIN offices o ON o.id=r.office_id WHERE r.status='pending' AND r.created_by<>? $where");$aq->execute([user()['id'],...$args]);$activityLabel='AWAITING YOUR REVIEW';$activityValue=(string)(int)$aq->fetchColumn();$activityFoot='Requests awaiting your decision';$showActivity=can_access('procurement');}elseif($roleCode==='AUDITOR'){$aq=$pdo->prepare('SELECT COUNT(*) FROM audit_logs a'.($of?' WHERE a.office_id=?':($rg?' JOIN offices o ON o.id=a.office_id WHERE o.id=? OR o.region_id=?':'')));$aq->execute($of?[$of]:($rg?[$rg,$rg]:[]));$activityLabel='AUDIT EVENTS';$activityValue=number_format((int)$aq->fetchColumn());$activityFoot='Recorded actions';$showActivity=can_access('audit');}else{$sa="SELECT COALESCE(SUM(total_amount),0) FROM sales_orders s JOIN offices o ON o.id=s.office_id WHERE s.sale_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')";$saArgs=[];if($of){$sa.=' AND s.office_id=?';$saArgs[]=$of;}elseif($rg){$sa.=' AND (s.office_id=? OR o.region_id=?)';$saArgs[]=$rg;$saArgs[]=$rg;}$aq=$pdo->prepare($sa);$aq->execute($saArgs);$activityValue='₹ '.number_format((float)$aq->fetchColumn(),2);}layout('Overview',function()use($stats,$recent,$stock,$vendors,$context,$activityLabel,$activityValue,$activityFoot,$showActivity){?><div class="hero"><small>OPERATIONS SNAPSHOT · <?=e(user()['role_name'])?></small><h2>Good <?=date('H')<12?'morning':(date('H')<17?'afternoon':'evening')?>, <?=e(strtok(user()['name'],' '))?></h2><p><?=e($context)?></p><strong>J</strong></div><div class="metrics"><?php if(can_access('procurement')):?><article><small>AWAITING APPROVAL</small><b><?=$stats['pending']?></b><span>Purchase requisitions</span></article><article><small>APPROVED REQUESTS</small><b><?=$stats['approved']?></b><span>Ready for procurement</span></article><?php endif;?><?php if(can_access('inventory')):?><article><small>STOCK ON HAND</small><b><?=number_format((float)$stock)?></b><span>Units in your scope</span></article><?php endif;?><?php if($showActivity):?><article><small><?=e($activityLabel)?></small><b><?=e($activityValue)?></b><span><?=e($activityFoot)?></span></article><?php endif;?></div><?php if(can_access('procurement')):?><div class="section"><div><h3>Recent requisitions</h3><p>Latest procurement activity in your scope</p></div><a href="<?=e(url('requisitions'))?>">View all →</a></div><div class="card"><?php req_table($recent);?></div><?php endif;?><div class="notes"><div><b>◎　Organization-wide visibility</b><p>Records are scoped to your assigned office and regional hierarchy.</p></div><div><b>◷　Audit-ready workflow</b><p>Key approvals and account actions are recorded in the audit trail.</p></div></div><?php });exit;}
if($path==='requisitions/new'&&$method==='POST'){role('ADMIN','HO_MANAGER','RO_MANAGER','DPC_OFFICER');verify_csrf();$title=trim($_POST['title']??'');$qty=(float)($_POST['quantity']??0);$amt=(float)($_POST['estimated_amount']??0);$productId=(int)($_POST['product_id']??0);$requiredDate=$_POST['required_date']??'';if(mb_strlen($title)<4||mb_strlen($title)>180||!is_numeric($_POST['quantity']??null)||$qty<=0||$qty>99999999999.999||!is_numeric($_POST['estimated_amount']??null)||$amt<0||$amt>999999999999.99||!$productId||!valid_iso_date((string)$requiredDate)||$requiredDate<date('Y-m-d')){flash('Enter a valid title, product, future required date, positive quantity and non-negative amount.','error');go('requisitions/new');}$q=$pdo->prepare("INSERT INTO requisitions(office_id,created_by,product_id,title,description,quantity,required_date,estimated_amount,status) VALUES(?,?,?,?,?,?,?,?,'pending')");$q->execute([user()['office_id'],user()['id'],$productId,$title,trim($_POST['description']??''),$qty,$requiredDate,$amt]);$id=$pdo->lastInsertId();$pdo->prepare("INSERT INTO requisition_events(requisition_id,user_id,event,comment) VALUES(?,?,'submitted','Submitted for approval')")->execute([$id,user()['id']]);audit($pdo,'submit','requisition',$id,['title'=>$title]);flash('Requisition submitted for approval.');go('requisitions');}
if($path==='requisitions'&&$method==='POST'){role('ADMIN','HO_MANAGER','RO_MANAGER','APPROVER');verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$status=$action==='approve'?'approved':($action==='reject'?'rejected':'');$q=$pdo->prepare('SELECT r.* FROM requisitions r JOIN offices o ON o.id=r.office_id WHERE r.id=? AND r.status="pending" AND (?="ADMIN" OR r.office_id=? OR o.region_id=?)');$q->execute([$id,user()['role_code'],user()['office_id'],user()['region_id']]);$r=$q->fetch();if(!$r||!$status||(int)$r['created_by']===(int)user()['id']){flash('Request is unavailable or maker cannot approve their own request.','error');go('requisitions');}$pdo->prepare('UPDATE requisitions SET status=?,approved_by=?,approved_at=NOW() WHERE id=?')->execute([$status,user()['id'],$id]);$pdo->prepare('INSERT INTO requisition_events(requisition_id,user_id,event,comment) VALUES(?,?,?,?)')->execute([$id,user()['id'],$status,trim($_POST['comment']??'')]);audit($pdo,$status,'requisition',$id);flash('Requisition '.($status==='approved'?'approved.':'returned.'));go('requisitions');}
if($path==='requisitions/new'){role('ADMIN','HO_MANAGER','RO_MANAGER','DPC_OFFICER');$products=$pdo->query('SELECT id,sku,name FROM products WHERE active=1 ORDER BY name')->fetchAll();layout('New requisition',function()use($products){?><div class="card formcard"><h3>Purchase requisition</h3><p>Provide the business need and estimated value for approval.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Requested product<select name="product_id" required><option value="">Select product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' - '.$p['name'])?></option><?php endforeach;?></select></label><label>Required by<input type="date" name="required_date" min="<?=date('Y-m-d')?>" required></label><label class="wide">Request title<input name="title" minlength="4" maxlength="180" required placeholder="e.g. Jute bag procurement — Q2"></label><label>Quantity<input type="number" name="quantity" min="0.001" step="0.001" required></label><label>Estimated amount (INR)<input type="number" name="estimated_amount" min="0" step="0.01" required></label><label class="wide">Business justification<textarea name="description" rows="4" maxlength="2000"></textarea></label><div class="actions"><a href="<?=e(url('requisitions'))?>">Cancel</a><button class="btn">Submit for approval →</button></div></form></div><?php });exit;}
if($path==='requisitions'){require_access('procurement','view');[$of,$rg]=scope();$sql='SELECT r.*,o.name office_name,u.name requester,p.sku product_sku,p.name product_name,au.name approved_by_name FROM requisitions r JOIN offices o ON o.id=r.office_id JOIN users u ON u.id=r.created_by LEFT JOIN products p ON p.id=r.product_id LEFT JOIN users au ON au.id=r.approved_by WHERE 1=1';$a=[];if($of){$sql.=' AND r.office_id=?';$a[]=$of;}elseif($rg){$sql.=' AND (o.id=? OR o.region_id=?)';$a[]=$rg;$a[]=$rg;}$sql.=' ORDER BY r.created_at DESC';$q=$pdo->prepare($sql);$q->execute($a);$rows=$q->fetchAll();layout('Procurement',function()use($rows){?><div class="card"><div class="section"><div><h3>Purchase requisitions</h3><p><?=count($rows)?> records in your organization scope</p></div></div><?php req_table($rows,true);?></div><?php });exit;}
if($path==='vendors'||$path==='inventory'){[$of,$rg]=scope();if($path==='vendors'){$sql='SELECT v.*,o.name office_name FROM vendors v LEFT JOIN offices o ON o.id=v.office_id WHERE 1=1';$a=[];if($of){$sql.=' AND (v.office_id=? OR v.office_id IS NULL)';$a[]=$of;}elseif($rg){$sql.=' AND (o.region_id=? OR v.office_id IS NULL)';$a[]=$rg;}$sql.=' ORDER BY v.name';$q=$pdo->prepare($sql);$q->execute($a);$rows=$q->fetchAll();layout('Vendors',function()use($rows){?><div class="card"><div class="section"><div><h3>Vendor register</h3><p>Supplier records visible in your scope</p></div></div><div class="scroll"><table><tr><th>VENDOR</th><th>GSTIN</th><th>EMAIL</th><th>OFFICE</th><th>STATUS</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['vendor_code'])?></small></td><td><?=e($r['gstin']?:'—')?></td><td><?=e($r['email']?:'—')?></td><td><?=e($r['office_name']?:'All offices')?></td><td><em class="approved">ACTIVE</em></td></tr><?php endforeach;?></table></div></div><?php });}else{$sql='SELECT i.*,o.name office_name FROM inventory_items i JOIN offices o ON o.id=i.office_id WHERE 1=1';$a=[];if($of){$sql.=' AND i.office_id=?';$a[]=$of;}elseif($rg){$sql.=' AND o.region_id=?';$a[]=$rg;}$sql.=' ORDER BY i.item_name';$q=$pdo->prepare($sql);$q->execute($a);$rows=$q->fetchAll();layout('Inventory',function()use($rows){?><div class="card"><div class="section"><div><h3>Stock on hand</h3><p>Quantities by office item record</p></div></div><div class="scroll"><table><tr><th>ITEM</th><th>CODE</th><th>OFFICE</th><th>QUANTITY</th><th>UNIT</th><th>REORDER LEVEL</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['item_name'])?></b></td><td><?=e($r['item_code'])?></td><td><?=e($r['office_name'])?></td><td><?=number_format($r['quantity'],2)?></td><td><?=e($r['unit'])?></td><td><?=number_format($r['reorder_level'],2)?></td></tr><?php endforeach;?></table></div></div><?php });}exit;}
if($path==='users'){role('ADMIN','AUDITOR');$rows=$pdo->query('SELECT u.*,r.name role_name,o.name office_name FROM users u JOIN roles r ON r.id=u.role_id JOIN offices o ON o.id=u.office_id ORDER BY u.name')->fetchAll();layout('Access management',function()use($rows){?><div class="card"><div class="section"><div><h3>User directory</h3><p>Account roles and organization assignment</p></div></div><div class="scroll"><table><tr><th>USER</th><th>ROLE</th><th>OFFICE</th><th>LAST SIGN IN</th><th>STATE</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['email'])?></small></td><td><?=e($r['role_name'])?></td><td><?=e($r['office_name'])?></td><td><?=e($r['last_login_at']?:'Never')?></td><td><?=e($r['is_active']?'ACTIVE':'DISABLED')?></td></tr><?php endforeach;?></table></div></div><?php });exit;}
if($path==='audit'){role('ADMIN','AUDITOR');$rows=$pdo->query('SELECT a.*,u.name user_name,o.name office_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN offices o ON o.id=a.office_id ORDER BY a.created_at DESC LIMIT 200')->fetchAll();layout('Audit trail',function()use($rows){?><div class="card"><div class="section"><div><h3>Recent activity</h3><p>Latest 200 recorded actions</p></div></div><div class="scroll"><table><tr><th>TIME</th><th>USER</th><th>ACTION</th><th>RECORD</th><th>OFFICE</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['user_name']?:'System')?></td><td><?=e(strtoupper($r['action']))?></td><td><?=e($r['entity_type'])?> #<?=e($r['entity_id'])?></td><td><?=e($r['office_name']?:'—')?></td></tr><?php endforeach;?></table></div></div><?php });exit;}
